    case "recent":
      // Find the folders that were most recently used as destinations.
      specialFolders = lazy.FolderUtils.getMostRecentFolders(
        specialFolders,
        Services.prefs.getIntPref("mail.folder_widget.max_recent"),
        "MRMTime"
      );
      break;
